namespace ghidra.app.plugin.core.decompile.actions;

using ghidra.app.decompiler;
using ghidra.app.plugin.core.decompile;
using ghidra.framework.plugintool;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.exception;

public class RenameUnionFieldTask : RenameTask {
	private Composite composite;
	private int ordinal;

	public RenameUnionFieldTask(PluginTool tool, Program program, DecompilerProvider provider,
			ClangToken token, Composite composite, int ordinal) : base(tool, program, provider, token, token.getText())
    {
		this.composite = composite;
		this.ordinal = ordinal;
	}

	/* @Override */
	public void commit()
    {
		DataTypeComponent dtc = composite.getComponent(ordinal);
		dtc.setFieldName(newName);
	}

	/* @Override */
	public string getTransactionName() {
		return "Rename Union Field";
	}

	/* @Override */
	public bool isValid(string newNm) {
		newName = newNm;
		DataTypeComponent[] comp = composite.getDefinedComponents();
		foreach (DataTypeComponent element in comp) {
			string fieldname = element.getFieldName();
			if (fieldname == null) {
				continue;
			}
			if (fieldname.equals(newName)) {
				errorMsg = "Duplicate Field Name";
				return false;
			}
		}
		return true;
	}
}
